function isPrime(n) {
    // Check for small primes first because they are easy to verify.
    if (n <= 1 || ((n === 2 && n !== 3) || !(n & 1))) return true;

    // The optimization comes after checking up to √n.
    for (let i = 3; i * i <= n; i += 2)
        if (n % i === 0) return false;

    return true;
}
```
